use strict;
use warnings;

my ($x, $y, $z) = (1, 2, 3);
print "x=$x y=$y z=$z\n";
($x, $y) = ($y, $x);
print "swapped: x=$x y=$y\n";
my ($p, $q, $r) = (1, 2);
print "r is ", (defined $r ? $r : "undef"), "\n";
my ($only) = (10, 20, 30);
print "only=$only\n";
my $lastone = (10, 20, 30)[-1];
print "last of a list literal: $lastone\n";
my ($a1, $b1) = (10, 20, 30)[0, 2];
print "list slice into two: $a1 $b1\n";
my @nums = (1 .. 5);
my ($head, @tail) = @nums;
print "head=$head tail=@tail\n";
my $count = () = (10, 20, 30, 40);
print "count via the goatse idiom: $count\n";
my @combined = (@nums, 6, 7);
print "combined=@combined (", scalar(@combined), ")\n";
my @nested = (1, (2, 3), (4, (5, 6)));
print "lists never nest: @nested (", scalar(@nested), ")\n";
my ($f1, $f2, $f3) = split /,/, "one,two,three";
print "split into three: $f1 $f2 $f3\n";
my @pairs = (apple => 1, banana => 2);
print "fat comma is a comma: @pairs\n";
my $n = @nums;
my ($firstelem) = @nums;
print "scalar context gives $n, list context gives $firstelem\n";
my ($u, $v);
($u, $v) = (7);
print "u=$u v=", (defined $v ? $v : "undef"), "\n";
